import sys
import requests
import json
from bs4 import BeautifulSoup
from urllib.parse import urlparse

def process_feed(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'xml')
        channel = soup.find('channel')
        if not channel:
            return {'url': url, 'error': 'no channel element found'}

        title = channel.find('title').get_text(strip=True) if channel.find('title') else None
        items = []
        for item in channel.find_all('item'):
            item_data = {
                'title': item.find('title').get_text(strip=True) if item.find('title') else None,
                'link': item.find('link').get_text(strip=True) if item.find('link') else None,
                'pubDate': item.find('pubDate').get_text(strip=True) if item.find('pubDate') else None
            }
            items.append(item_data)

        return {
            'url': url,
            'title': title,
            'items': items
        }
    except requests.RequestException as e:
        return {'url': url, 'error': f'could not retrieve the resource: {str(e)}'}
    except Exception as e:
        return {'url': url, 'error': f'could not read the response body as RSS 2.0: {str(e)}'}

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    urls_file = sys.argv[1]
    output_file = sys.argv[2]

    with open(urls_file, 'r', encoding='utf-8') as f:
        urls = [line.strip() for line in f if line.strip() and not line.strip().startswith('#')]

    digest = []
    for url in urls:
        digest.append(process_feed(url))

    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(digest, f, ensure_ascii=False, indent=2)

if __name__ == '__main__':
    main()

import sys
import json
import requests
from bs4 import BeautifulSoup
from urllib.parse import urlparse

def fetch_rss(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        return None

def parse_rss(rss_text):
    if not rss_text:
        return None
    try:
        soup = BeautifulSoup(rss_text, 'xml')
        channel = soup.find('channel')
        if not channel:
            return None

        channel_title = channel.title.get_text(strip=True) if channel.title else None

        items = []
        for item in channel.find_all('item'):
            item_title = item.title.get_text(strip=True) if item.title else ''
            items.append(item_title)

        return {'title': channel_title, 'items': items}
    except Exception:
        return None

def process_urls(urls_file, output_file):
    with open(urls_file, 'r', encoding='utf-8') as f:
        urls = [line.strip() for line in f if line.strip()]

    result = []
    for url in urls:
        rss_text = fetch_rss(url)
        if rss_text:
            rss_data = parse_rss(rss_text)
            if rss_data:
                result.append({
                    'url': url,
                    'title': rss_data['title'],
                    'items': rss_data['items']
                })
            else:
                result.append({'url': url, 'error': 'Invalid RSS format'})
        else:
            result.append({'url': url, 'error': 'Failed to fetch URL'})

    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print("Usage: python feeddigest.py <urls_file> <output_file>")
        sys.exit(1)
    process_urls(sys.argv[1], sys.argv[2])

import sys
import json
import requests
from bs4 import BeautifulSoup
import xml.etree.ElementTree as ET

def fetch_rss(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return response.text
    except requests.RequestException:
        return None

def parse_rss(xml_content):
    try:
        root = ET.fromstring(xml_content)
        items = []
        for item in root.findall('.//item'):
            title = item.find('title')
            if title is not None:
                items.append(title.text)
        return items
    except ET.ParseError:
        return []

def process_urls(urls_file, output_file):
    with open(urls_file, 'r', encoding='utf-8') as f:
        urls = [line.strip() for line in f if line.strip()]

    result = {}
    for url in urls:
        rss_content = fetch_rss(url)
        if rss_content:
            titles = parse_rss(rss_content)
            result[url] = titles

    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False, indent=2)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python feeddigest.py <urls_file> <output_file>")
        sys.exit(1)

    process_urls(sys.argv[1], sys.argv[2])

import sys
import json
import requests
import xml.etree.ElementTree as ET

def fetch_rss_titles(urls_file, output_file):
    urls = []
    with open(urls_file, 'r', encoding='utf-8') as f:
        for line in f:
            url = line.strip()
            if url:
                urls.append(url)

    results = {}
    for url in urls:
        try:
            response = requests.get(url)
            response.raise_for_status()
            root = ET.fromstring(response.content)
            titles = [item.find('title').text for item in root.findall('.//item')]
            results[url] = titles
        except Exception as e:
            results[url] = str(e)

    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(results, f, ensure_ascii=False, indent=4)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print('Usage: python feeddigest.py <urls_file> <output_file>')
        sys.exit(1)
    urls_file = sys.argv[1]
    output_file = sys.argv[2]
    fetch_rss_titles(urls_file, output_file)
